\definecolor{cardtitle2}{HTML}{0A3040}   % teal card header bg
\definecolor{cardtitlegold}{HTML}{1A2A0A} % gold card header
\definecolor{textlight}{HTML}{E8F0FE}    % near-white text
\definecolor{textmid}{HTML}{90CAF9}      % light blue secondary text
\definecolor{textgray}{HTML}{B0BEC5}     % grey caption text
\definecolor{stathighlight}{HTML}{0A3060} % stat callout bg
\definecolor{goldtint}{HTML}{1A1500}     % gold-tinted dark bg
\definecolor{tealtint}{HTML}{00251A}     % teal-tinted dark bg
\definecolor{bluetint}{HTML}{0A1929}     % blue-tinted dark bg

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=22pt, itemsep=8pt, parsep=0pt, topsep=4pt,
  label={\color{gold}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=26pt, itemsep=8pt, parsep=0pt, topsep=4pt,
  label={\color{secondary}\bfseries\arabic*.}}

% ── Card styles (left accent stripe, dark neural theme) ──
\tcbset{
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
