    \fontsize{28}{36}\selectfont\color{textlight} #2: \textbf{#3}
  \end{tcolorbox}%
  \vspace{2pt}%
}

% ── Step arrow for methods pipeline ──
\newcommand{\pipelinestep}[2]{%
  \begin{tcolorbox}[enhanced, arc=2pt, boxrule=0pt, colback=secondary!25!cardbg,
    borderline west={3pt}{0pt}{secondary},
    left=8pt, right=6pt, top=3pt, bottom=3pt, width=0.97\linewidth]
    \fontsize{27}{34}\selectfont
    {\color{gold}\bfseries #1}\quad{\color{textlight} #2}
  \end{tcolorbox}%
  \vspace{2pt}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ════════════════════════════════════════════════
% TITLE BAR  (rows top → row4, span 3)
% ════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  borderline south={3pt}{0pt}{gold},
  drop shadow={opacity=0.45},
]{name=title, column=1, span=3, between=top and row4}{%
  {\fontsize{72}{86}\selectfont\bfseries\color{textlight}
    Mapping Neural Circuit Architecture}\\[8pt]
  {\fontsize{52}{62}\selectfont\bfseries\color{gold}
    Advances in Brain Connectivity Analysis}\\[10pt]
  {\fontsize{30}{38}\selectfont\color{textmid}
    Large-Scale Connectomics Reveals New Principles of Cortical Circuit Organization}\\[10pt]
  {\fontsize{26}{34}\selectfont\color{textgray}
    Connectomics Research Consortium\quad$\bullet$\quad
    \textit{Nature} \textbf{2024}\quad$\bullet$\quad
    DOI: 10.1038/s41586-024-07487-w\quad$\bullet$\quad
    Neuroscience Symposium}
}

% ════════════════════════════════════════════════
% STATS BANNER  (rows row4 → row6, span 3)
% ════════════════════════════════════════════════
\posterbox[
  enhanced, colback=bluetint, colframe=bluetint, arc=0pt, boxrule=0pt,
  left=10pt, right=10pt, top=8pt, bottom=8pt,
  valign=center,
  borderline south={2pt}{0pt}{secondary!50},
]{name=stats, column=1, span=3, between=row4 and row6}{%
  \centering
  \begin{minipage}[c]{0.235\linewidth}\centering
    \metricbox{\raise1pt\hbox{\textasciitilde}125K}{Neurons Mapped}{Full reconstruction}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \metricbox{\raise1pt\hbox{\textasciitilde}54M}{Synaptic Connections}{Individually identified}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \metricbox{37}{Circuit Motifs}{Recurring building blocks}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \metricbox{94.2\%}{Classification Accuracy}{Automated neuron typing}
  \end{minipage}
}

% ════════════════════════════════════════════════
% COLUMN 1 — Background + Methodology
% ════════════════════════════════════════════════

\posterbox[navycard, title={Background \& Motivation}
]{name=background, column=1, between=row6 and row11}{%
  \fontsize{28}{38}\selectfont
  Understanding brain computation demands complete, high-resolution wiring diagrams. Prior work lacked:
  \begin{itemize}
    \item Scale: single neurons or small patches only
    \item Precision: light microscopy insufficient for synapses
    \item Integration: imaging and functional validation separate
  \end{itemize}
  \vspace{6pt}
  \begin{tcolorbox}[enhanced, arc=3pt, boxrule=0pt,
    colback=secondary!22!cardbg, borderline west={3pt}{0pt}{secondary},
    left=10pt, right=8pt, top=6pt, bottom=6pt]
    \fontsize{27}{34}\selectfont\color{textlight}
    \textbf{Gap:} No dataset captured circuit-level wiring at cortex scale with functional validation --- until now.
  \end{tcolorbox}
  \vspace{6pt}
  \begin{tcolorbox}[enhanced, arc=3pt, boxrule=0pt,
    colback=gold!18!cardbg, borderline west={3pt}{0pt}{gold},
    left=10pt, right=8pt, top=6pt, bottom=6pt]
    \fontsize{27}{34}\selectfont\color{textlight}
    \textbf{This study:} EM imaging $\to$ ML segmentation $\to$ graph analysis $\to$ functional validation, at cortex-wide scale.
  \end{tcolorbox}
}

\posterbox[tealcard, title={Methodology Pipeline}
]{name=methods, column=1, between=row11 and row20}{%
  \fontsize{27}{36}\selectfont
  \vspace{2pt}
  \pipelinestep{01}{Serial-section EM at 4$\times$4$\times$30 nm resolution}
  \pipelinestep{02}{Deep learning neuron tracing + human proofreading}
  \pipelinestep{03}{CNN synapse classifier — 94.2\% accuracy}
  \pipelinestep{04}{Graph-theoretic motif detection \& clustering}
  \pipelinestep{05}{Ca\textsuperscript{2+} imaging + optogenetic validation}

  \vspace{8pt}
  {\color{textmid}\fontsize{26}{34}\selectfont\bfseries Dataset Scale}
  \vspace{4pt}

  \renewcommand{\arraystretch}{1.55}
  {\fontsize{24}{30}\selectfont\color{textlight}
  \begin{tabular}{>{\color{textmid}\bfseries}p{0.42\linewidth}
                  >{\color{gold}}p{0.50\linewidth}}
    Neurons & $\sim$125,000 \\
    Synapses & $\sim$54 million \\
    EM resolution & 4$\times$4$\times$30 nm \\
    Classification acc. & 94.2\% \\
    Validation method & Optogenetics + Ca\textsuperscript{2+} \\
  \end{tabular}
  }

  \vspace{8pt}
  \begin{tcolorbox}[enhanced, arc=3pt, boxrule=0pt,
    colback=accent!20!cardbg, borderline west={3pt}{0pt}{accent},
    left=10pt, right=8pt, top=6pt, bottom=6pt]
    \fontsize{26}{34}\selectfont\color{textlight}
    One of the most comprehensive connectomic resources ever assembled --- open-access.
  \end{tcolorbox}
}

% ════════════════════════════════════════════════
% COLUMN 2 — Key Findings (primary content)
% ════════════════════════════════════════════════

\posterbox[goldcard, title={Key Findings}
]{name=findings, column=2, between=row6 and row20}{%
  \fontsize{29}{40}\selectfont

  % Finding 1
  \begin{tcolorbox}[enhanced, arc=4pt, boxrule=0pt,
    colback=gold!20!cardbg, borderline={1.5pt}{0pt}{gold!70},
    left=12pt, right=10pt, top=8pt, bottom=8pt]
    {\fontsize{44}{52}\selectfont\bfseries\color{gold} 37 Connectivity Motifs}\\[4pt]
    {\fontsize{28}{36}\selectfont\color{textlight}
    Distinct recurring circuit patterns identified --- a \textit{finite vocabulary} of wiring logic, analogous to logic gates in digital circuits.}
  \end{tcolorbox}
  \vspace{8pt}

  % Finding 2
  \begin{tcolorbox}[enhanced, arc=4pt, boxrule=0pt,
    colback=secondary!22!cardbg, borderline={1.5pt}{0pt}{secondary!70},
    left=12pt, right=10pt, top=8pt, bottom=8pt]
    {\fontsize{44}{52}\selectfont\bfseries\color{textmid} Hub Neurons}\\[4pt]
    {\fontsize{28}{36}\selectfont\color{textlight}
    Only \textbf{3.5\%} of neurons drive \textbf{28\%} of total synaptic output --- highly non-uniform influence distribution.}\\[4pt]
    {\fontsize{26}{34}\selectfont\color{textgray}
    $\Rightarrow$ Focal lesions / stimulation produce outsized network effects.}
  \end{tcolorbox}
  \vspace{8pt}

  % Finding 3
  \begin{tcolorbox}[enhanced, arc=4pt, boxrule=0pt,
    colback=accent!20!cardbg, borderline={1.5pt}{0pt}{accent!70},
    left=12pt, right=10pt, top=8pt, bottom=8pt]
    {\fontsize{44}{52}\selectfont\bfseries\color{accent} Layer-Specific Rules}\\[4pt]
    {\fontsize{28}{36}\selectfont\color{textlight}
    Feedforward connections dominate L2/3$\to$L4; recurrent connections enriched in L5 at \textbf{4.7:1} ratio (recurrent:feedforward).}
  \end{tcolorbox}
  \vspace{8pt}

  % Finding 4
  \begin{tcolorbox}[enhanced, arc=4pt, boxrule=0pt,
    colback=gold!15!tealtint, borderline={1.5pt}{0pt}{gold!50},
    left=12pt, right=10pt, top=8pt, bottom=8pt]
    {\fontsize{44}{52}\selectfont\bfseries\color{gold} Inhibitory Specificity}\\[4pt]
    {\fontsize{28}{36}\selectfont\color{textlight}
    Inhibitory interneurons wire with \textbf{6.2$\times$ higher specificity} than excitatory neurons --- challenges blanket inhibition hypothesis.}\\[4pt]
    {\fontsize{26}{34}\selectfont\color{textgray}
    $\Rightarrow$ Precise inhibitory targeting, not diffuse suppression.}
  \end{tcolorbox}
  \vspace{8pt}

  % Summary table
  {\color{textmid}\fontsize{26}{34}\selectfont\bfseries Quantitative Summary}
  \vspace{6pt}

  \renewcommand{\arraystretch}{1.5}
  {\fontsize{24}{30}\selectfont
  \begin{tabular}{>{\color{textgray}}p{0.50\linewidth}
                  >{\color{gold}\bfseries}p{0.42\linewidth}}
    \rowcolor{secondary!15!cardbg}
    Connectivity motifs & 37 types \\
    Hub neuron fraction & 3.5\% $\to$ 28\% output \\
    \rowcolor{secondary!15!cardbg}
    L5 recurrent ratio & 4.7:1 \\
    Inhibitory specificity & 6.2$\times$ vs.\ excitatory \\
    \rowcolor{secondary!15!cardbg}
    Neurons mapped & $\sim$125,000 \\
    Synapses catalogued & $\sim$54 million \\
  \end{tabular}
  }
}

% ════════════════════════════════════════════════
% COLUMN 3 — Implications + Citation
% ════════════════════════════════════════════════

\posterbox[tealcard, title={Implications for Neuroscience}
]{name=implications, column=3, between=row6 and row14}{%
  \fontsize{28}{38}\selectfont

  \subheader{Circuit Computation}
  \begin{itemize}
    \item Modular motifs $\Rightarrow$ finite wiring vocabulary
    \item Brain uses reusable circuit elements at scale
    \item Opens path to cortical circuit ``periodic table''
  \end{itemize}

  \vspace{6pt}
  \subheader{Clinical \& BCI Relevance}
  \begin{itemize}
    \item Hub neuron maps $\Rightarrow$ predict lesion effects
    \item Targeted stimulation design for BCI
    \item Neurological disease focal mechanisms
  \end{itemize}

  \vspace{8pt}
  \begin{tcolorbox}[enhanced, arc=3pt, boxrule=0pt,
    colback=accent!22!cardbg, borderline west={4pt}{0pt}{accent},
    left=10pt, right=8pt, top=6pt, bottom=6pt]
    \fontsize{27}{34}\selectfont\color{textlight}
    \textbf{Open Access:} Full dataset \& analysis tools released --- expected to accelerate discovery across the field.
  \end{tcolorbox}
}

\posterbox[navycard, title={Future Directions}
]{name=future, column=3, between=row14 and row18}{%
  \fontsize{28}{38}\selectfont
  \begin{enumerate}
    \item Extend connectomics to additional brain regions
    \item Cross-species comparative circuit analysis
    \item Complete mammalian brain wiring diagram
    \item Integrate with in-vivo functional recordings
  \end{enumerate}
  \vspace{6pt}
  \begin{tcolorbox}[enhanced, arc=3pt, boxrule=0pt,
    colback=gold!15!cardbg, borderline west={3pt}{0pt}{gold},
    left=10pt, right=8pt, top=5pt, bottom=5pt]
    \fontsize{26}{34}\selectfont\color{textlight}
    \textbf{Vision:} Complete wiring diagram of the mammalian brain.
  \end{tcolorbox}
}

\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=3, between=row18 and row20}{%
  \fontsize{27}{36}\selectfont
  \begin{itemize}[label={\color{gold}$\star$}]
    \item Step-change in scale \& precision of connectomics
    \item Brain employs finite, reusable circuit motifs
    \item Hub neurons disproportionately drive network activity
    \item Inhibition is precise, not diffuse
  \end{itemize}
}

\end{tcbposter}
\end{document}

